    public static string Humanize(string name, string component)
    {
        var s = name;
        if (s.StartsWith("--p-", StringComparison.Ordinal)) s = s["--p-".Length..];
        else if (s.StartsWith(".p-", StringComparison.Ordinal)) s = s[".p-".Length..];
        if (s.StartsWith(component, StringComparison.OrdinalIgnoreCase) && s.Length > component.Length && s[component.Length] == '-')
            s = s[(component.Length + 1)..];
        else if (s.Equals(component, StringComparison.OrdinalIgnoreCase))
            s = "root";
        if (s.Length == 0) return component;
        var translated = string.Join(' ', s.Split('-').Select(Translate));
        return char.ToUpperInvariant(component[0]) + component[1..] + " " + translated;
    }

    private static string Translate(string word) =>
        Words.TryGetValue(word, out var pt) ? pt : word;
